package org.humanjourney.core.mapfeature;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.humanjourney.core.mapfeature.GeometryV2Test.*;
class GeometryV2ValidationTest {
 @AfterEach void reset(){FeatureCatalog.reset();}
 @Test void outsideAndOuterTouchingHolesRejectCompleteFeature(){for(String hole:List.of("[[210,10],[230,10],[230,30],[210,30]]","[[0,20],[20,20],[20,40],[0,40]]","[[190,20],[210,20],[210,40],[190,40]]"))assertThrows(RuntimeException.class,()->feature(polygon("bad",OUTER,"["+hole+"]",1)));}
 @Test void holesWhoseEdgesLeaveConcaveOuterAreRejectedEvenWithVerticesInside(){String outer="[[0,0],[200,0],[200,200],[150,200],[150,50],[50,50],[50,200],[0,200]]";String hole="[[25,100],[175,100],[175,125],[25,125]]";assertThrows(RuntimeException.class,()->feature(polygon("bad",outer,"["+hole+"]",1)));}
 @Test void holesCannotOverlapTouchOrContainEachOther(){for(String hole:List.of("[[75,75],[125,75],[125,125],[75,125]]","[[100,50],[125,50],[125,100],[100,100]]","[[60,60],[90,60],[90,90],[60,90]]","[[25,25],[125,25],[125,125],[25,125]]"))assertThrows(RuntimeException.class,()->feature(polygon("bad",OUTER,"["+HOLE+","+hole+"]",1)));}
 @Test void malformedOuterAndHoleRingsAreRejected(){for(String ring:List.of("[]","[[0,0],[10,10]]","[[0,0],[10,10],[0,10],[10,0]]","[[0,0],[100,0],[50,0],[100,100],[0,100]]","[[0,0],[0.0,-0.0],[10,10]]")){assertThrows(RuntimeException.class,()->feature(polygon("bad",ring,"[]",1)));assertThrows(RuntimeException.class,()->feature(polygon("bad",OUTER,"["+ring+"]",1)));}}
 @Test void emptyAndMalformedMultipartAndNestedDimensionFieldsReject(){for(String body:List.of("{\"type\":\"multipolygon\",\"polygons\":[]}","{\"type\":\"multipolygon\",\"polygons\":[{}]}","{\"type\":\"polygon\",\"outer\":"+OUTER+",\"dimension\":\"minecraft:the_nether\"}","{\"type\":\"polyline\",\"points\":[[0,0],[100,0]],\"holes\":[]}"))assertThrows(RuntimeException.class,()->feature(json("bad",2,body,1)));}
 @Test void unsupportedSchemaAndMixedLegacyFieldsAreRejected(){assertThrows(RuntimeException.class,()->feature(json("bad",3,"{\"type\":\"polygon\",\"outer\":"+OUTER+"}",1)));assertThrows(RuntimeException.class,()->feature(json("bad",1,"{\"type\":\"polygon\",\"outer\":"+OUTER+"}",1)));assertThrows(RuntimeException.class,()->feature(json("bad",2,"{\"type\":\"polygon\",\"points\":"+OUTER+"}",1)));}
 @Test void ringPartAndVertexLimitsRejectBeforeUnboundedConstruction(){var part=new FeatureGeometry.Part(circle(3,0,0,10),List.of());assertThrows(RuntimeException.class,()->FeatureGeometry.multipolygon(Collections.nCopies(129,part)));assertThrows(RuntimeException.class,()->new FeatureGeometry.Part(circle(3,0,0,100),Collections.nCopies(128,circle(3,0,0,1))));assertThrows(RuntimeException.class,()->circle(4097,0,0,100));var parts=new ArrayList<FeatureGeometry.Part>();for(int i=0;i<128;i++)parts.add(new FeatureGeometry.Part(circle(i==127?33:32,i*100,0,10),List.of()));assertThrows(RuntimeException.class,()->FeatureGeometry.multipolygon(parts));}
 @Test void catalogHasIndependentTotalVertexBudget(){var geometry=large();var views=new ArrayList<MapFeature.View>();for(int i=0;i<256;i++)views.add(view("f_"+i,geometry));assertDoesNotThrow(()->GeometryBudget.check(views));views.add(view("too_many",geometry));assertThrows(RuntimeException.class,()->GeometryBudget.check(views));}
 @Test void catalogHasIndependentRingBudgetEvenBelowVertexLimit(){var part=new FeatureGeometry.Part(circle(3,0,0,10),List.of());var geometry=FeatureGeometry.multipolygon(Collections.nCopies(128,part));var views=new ArrayList<MapFeature.View>();for(int i=0;i<512;i++)views.add(view("f_"+i,geometry));assertDoesNotThrow(()->GeometryBudget.check(views));views.add(view("too_many",geometry));assertThrows(RuntimeException.class,()->GeometryBudget.check(views));}
 @Test void realReloadRetainsWholePreviousCatalogAndProvidesFeatureRingContext()throws Exception{var loader=new FeatureReloadTest();loader.reload(polygon("good",OUTER,"["+HOLE+"]",1));var old=FeatureCatalog.state();loader.reload(polygon("replacement",OUTER,"[]",1),polygon("bad",OUTER,"[[[250,0],[260,0],[260,10],[250,10]]]",1));assertSame(old.data(),FeatureCatalog.state().data());assertEquals(old.revision(),FeatureCatalog.state().revision());assertTrue(FeatureCatalog.state().error().contains("bad"));assertTrue(FeatureCatalog.state().error().contains("hole[0]"));assertTrue(FeatureCatalog.state().error().contains("test:core/map_feature/"));}
 @Test void v2Allows4096PointPolylineButLegacyStillKeepsIts512Cap(){var points=new ArrayList<org.humanjourney.core.water.WaterGeography.Point>();for(int i=0;i<4096;i++)points.add(new org.humanjourney.core.water.WaterGeography.Point(i,i%2));assertEquals(4095,FeatureGeometry.polyline(points).segments());assertThrows(RuntimeException.class,()->new FeatureGeometry(FeatureGeometry.Kind.POLYLINE,points,null));}
 @Test void deliveredV2FixtureLoadsAlongsideUnchangedV1Examples()throws Exception{var root=java.nio.file.Path.of(System.getProperty("humanjourney.projectDir"));var files=new ArrayList<String>();for(String dir:List.of("example-map-features","example-map-features-v2"))try(var stream=java.nio.file.Files.list(root.resolve(dir+"/data/human_journey/core/map_feature"))){for(var p:stream.filter(p->p.toString().endsWith(".json")).sorted().toList())files.add(java.nio.file.Files.readString(p));}new FeatureReloadTest().reload(files.toArray(String[]::new));assertTrue(FeatureCatalog.state().error().isEmpty());assertEquals(6,FeatureCatalog.state().data().features().size());assertEquals(2,FeatureCatalog.state().data().features().values().stream().filter(f->f.schemaVersion()==1).count());assertEquals(4,FeatureCatalog.state().data().features().values().stream().filter(f->f.schemaVersion()==2).count());}
}
